@pytest.mark.parametrize("data", [
    {"id": 0, "email": "a@example.com", "name": "A"},
    {"id": 1, "email": "invalid", "name": "A"},
])
def test_invalid_user_rejected(data: dict[str, object]) -> None:
    with pytest.raises(ValidationError):
        User.parse_obj(data)

def test_nested_parse_and_serialization() -> None:
    order = Order.parse_obj({
        "id": 10,
        "customer": {"id": 1, "email": "ADA@EXAMPLE.COM", "name": " Ada "},
        "items": [
            {"sku": "pen", "quantity": 2, "unit_price_cents": 150},
            {"sku": "book", "quantity": 1, "unit_price_cents": 700},
        ],
        "total_cents": 1000,
    })
    assert isinstance(order.customer, User)
    assert isinstance(order.items[0], OrderItem)
    assert order.dict()["customer"] == {
        "id": 1, "email": "ada@example.com", "name": "Ada"
    }
    assert order.dict()["items"][0]["sku"] == "pen"

def test_order_total_matches_multiple_items() -> None:
    with pytest.raises(ValidationError, match="total does not match items"):
        Order.parse_obj({
            "id": 10,
            "customer": {"id": 1, "email": "a@example.com", "name": "A"},
            "items": [{"sku": "pen", "quantity": 2, "unit_price_cents": 150}],
            "total_cents": 299,
        })

class ShopModel(BaseModel):
    class Config:
        anystr_strip_whitespace = True
        extra = "forbid"
        validate_assignment = True

class OrderItem(ShopModel):
    sku: str
    quantity: int
    unit_price_cents: int

    @validator("quantity", "unit_price_cents")

class Order(ShopModel):
    id: int
    customer: User
    items: list[OrderItem]
    total_cents: int

    @root_validator

class User(ShopModel):
    id: int
    email: str
    name: str

    @validator("id")

@validator("quantity", "unit_price_cents")
def positive_amount(cls, value: int) -> int:
    if value <= 0:
        raise ValueError("amount must be positive")
    return value

@root_validator
def total_matches_items(cls, values: dict[str, object]) -> dict[str, object]:
    items = values.get("items")
    total = values.get("total_cents")
    if isinstance(items, list) and isinstance(total, int):
        expected = sum(item.quantity * item.unit_price_cents for item in items)
        if total != expected:
            raise ValueError("total does not match items")
    return values

@validator("id")
def positive_id(cls, value: int) -> int:
    if value <= 0:
        raise ValueError("id must be positive")
    return value

@validator("email")
def normalized_email(cls, value: str) -> str:
    value = value.lower()
    if "@" not in value or value.startswith("@") or value.endswith("@"):
        raise ValueError("invalid email")
    return value
